"""Triton fused stream-collide kernels (generated by :mod:`pylbm.codegen`)."""

from __future__ import annotations

from typing import Any

from ..codegen import load, spec_for
from ._fused import FusedSolver, cuda_ok

try:
    import triton

    _HAVE = True
except Exception:  # pragma: no cover
    _HAVE = False


class TritonFused(FusedSolver):
    """One Triton program per row segment of ``BLOCK`` nodes; pull scheme, two buffers."""

    backend = "triton"
    variant = "fused"
    description = "Triton fused stream+collide+BC, pull, SoA, two buffers"
    BLOCK = 128
    NUM_WARPS = 4

    @classmethod
    def available(cls) -> tuple[bool, str]:
        if not _HAVE:
            return False, "triton not installed"
        return cuda_ok()

    def _compile(self) -> None:
        p = self.problem
        pats = ("aa-odd", "aa-even") if self.aa else ("ab",)
        self.kernels = {pat: load(spec_for(p, self.storage, pat), "triton").lbm_kernel
                        for pat in pats}
        shp = tuple(p.shape) + (1,) * (3 - p.dim)
        self.grid = (triton.cdiv(shp[0], self.BLOCK), shp[1], shp[2])
        self.args = self.scalar_args()

    def _launch(self, which: str, src: Any, dst: Any) -> None:
        self.kernels[which][self.grid](src, dst, *self.args, BLOCK=self.BLOCK,
                                       num_warps=self.NUM_WARPS)


class TritonFusedAA(TritonFused):
    variant = "fused-aa"
    description = "Triton fused, AA-pattern in-place streaming (single buffer)"
    aa = True


class TritonFusedFP16(TritonFused):
    variant = "fused-fp16"
    description = "Triton fused, fp16 storage of f - w_i, fp32 arithmetic"
    storage = "f16"


class TritonFusedBF16(TritonFused):
    variant = "fused-bf16"
    description = "Triton fused, bf16 storage of f - w_i, fp32 arithmetic"
    storage = "bf16"


class TritonFusedAAFP16(TritonFused):
    variant = "fused-aa-fp16"
    description = "Triton fused, AA pattern + fp16 storage of f - w_i"
    storage = "f16"
    aa = True
